settings.custom_liquid:
{%- assign p = all_products['glow-professional-led-teeth-whitening-kit'] -%}
<div class="glow-hero">
  <div class="glow-hero__inner">
    <div class="glow-hero__copy">
      <p class="glow-hero__eyebrow">Professional-strength · At home</p>
      <h1 class="glow-hero__title">A visibly whiter smile<br>without the dentist bill</h1>
      <p class="glow-hero__sub">The GLOW LED whitening device uses the same blue-light technology dental clinics charge thousands for. One 30-minute session a day, in your own bathroom.</p>
      <div class="glow-hero__cta">
        {%- if p != blank -%}
          <a class="glow-hero__btn" href="{{ p.url }}">Get yours — {{ p.price | money }}</a>
        {%- else -%}
          <a class="glow-hero__btn" href="/collections/all">Shop now</a>
        {%- endif -%}
        <span class="glow-hero__note">Free delivery in South Africa</span>
      </div>
      <ul class="glow-hero__trust">
        <li>30-day money-back guarantee</li>
        <li>Enamel-safe, no sensitivity</li>
        <li>Tracked delivery, 3–5 days</li>
      </ul>
    </div>
    <div class="glow-hero__media">
      {%- if p != blank and p.featured_image -%}
        <img src="{{ p.featured_image | image_url: width: 1100 }}"
             alt="{{ p.featured_image.alt | escape }}"
             width="1100" height="1100" loading="eager" fetchpriority="high">
      {%- endif -%}
    </div>
  </div>
</div>
<style>
  .glow-hero{background:linear-gradient(135deg,#2C3E50 0%,#3A5A76 45%,#4A90E2 100%);}
  .glow-hero .glow-hero__copy,
  .glow-hero .glow-hero__copy h1,
  .glow-hero .glow-hero__copy p,
  .glow-hero .glow-hero__copy li,
  .glow-hero .glow-hero__copy span{color:#fff;}
  .glow-hero__inner{max-width:1200px;margin:0 auto;padding:56px 20px;display:grid;grid-template-columns:1.05fr .95fr;gap:44px;align-items:center;}
  .glow-hero .glow-hero__eyebrow{color:#D4AF37 !important;margin:0 0 14px;font-size:1.2rem;letter-spacing:.14em;text-transform:uppercase;color:#D4AF37;font-weight:600;}
  .glow-hero .glow-hero__title{color:#fff !important;margin:0 0 18px;font-size:4.4rem;line-height:1.08;font-weight:700;letter-spacing:-.01em;}
  .glow-hero__sub{margin:0 0 26px;font-size:1.7rem;line-height:1.6;max-width:34em;color:rgba(255,255,255,.92);}
  .glow-hero__cta{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin-bottom:24px;}
  .glow-hero .glow-hero__btn{color:#2C3E50 !important;display:inline-block;background:#D4AF37;color:#2C3E50;font-weight:700;font-size:1.7rem;padding:16px 34px;border-radius:6px;text-decoration:none;transition:transform .15s ease,box-shadow .15s ease;box-shadow:0 6px 18px rgba(0,0,0,.22);}
  .glow-hero__btn:hover{transform:translateY(-2px);box-shadow:0 10px 24px rgba(0,0,0,.28);}
  .glow-hero__note{font-size:1.4rem;color:rgba(255,255,255,.88);}
  .glow-hero__trust{list-style:none;margin:0;padding:0;display:flex;gap:22px;flex-wrap:wrap;font-size:1.35rem;color:rgba(255,255,255,.9);}
  .glow-hero__trust li{position:relative;padding-left:20px;}
  .glow-hero__trust li:before{content:"";position:absolute;left:0;top:.55em;width:9px;height:9px;border-radius:50%;background:#D4AF37;}
  .glow-hero__media img{width:100%;height:auto;display:block;border-radius:14px;box-shadow:0 18px 44px rgba(0,0,0,.3);}
  @media screen and (max-width:749px){
    .glow-hero__inner{grid-template-columns:1fr;gap:28px;padding:36px 18px;}
    .glow-hero__title{font-size:3.2rem;}
    .glow-hero__sub{font-size:1.5rem;}
    .glow-hero__media{order:-1;}
  }
</style>
